const item = $input.first().json.body || $input.first().json;

const tournamentName = item.tournamentName || 'Mana Community Championship';
const disruptionReason = item.disruptionReason || item.reason || 'Rain / Weather Delay';
const remainingMatches = item.remainingMatches || [];
const availableVenues = item.availableVenues || ['Ground A', 'Indoor Multi-Court'];
const availableHours = item.availableHours || 4;
const reserveDayAvailable = item.reserveDayAvailable ?? true;
const curfewTime = item.curfewTime || '22:00';

const prompt = `You are the Emergency Tournament Director and Operations Planner for the Mana Community Sports Council.
A major disruption has occurred during a live sports tournament.

Disruption Scenario:
- Tournament: ${tournamentName}
- Cause: ${disruptionReason}
- Remaining Matches To Play: ${JSON.stringify(remainingMatches, null, 2)}
- Available Venues: ${JSON.stringify(availableVenues)}
- Time Remaining Before Curfew (${curfewTime}): ${availableHours} hours
- Reserve Day Available: ${reserveDayAvailable ? 'YES' : 'NO'}

Task:
Formulate an emergency contingency recovery plan that guarantees athletic fairness, avoids back-to-back player exhaustion (< 30 min rest), and ensures the championship concludes legitimately.

Respond ONLY with a valid JSON object matching this schema:
{
  "contingencyStrategy": "COMPRESSED_FORMAT" | "RESERVE_DAY_ACTIVATION" | "VENUE_REALLOCATION" | "SHARED_TROPHY_CONTINGENCY",
  "revisedMatchDuration": string,
  "rescheduledFixtures": [
    {
      "matchId": string | number,
      "matchName": string,
      "revisedVenue": string,
      "revisedTime": string,
      "formatAdjustment": string
    }
  ],
  "tiebreakerRuling": "Fair-play criteria for any abandoned matches that cannot be rescheduled",
  "directorOfficialStatement": "Authoritative, reassuring communication to teams explaining the necessary schedule changes",
  "emergencyWhatsAppBroadcast": "Urgent, clear WhatsApp bulletin with emojis ready to send to team captains and community group"
}`;

return [{
  json: {
    tournamentName,
    disruptionReason,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsedPlan = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedPlan = JSON.parse(rawText);
} catch (err) {
  parsedPlan = {
    contingencyStrategy: "RESERVE_DAY_ACTIVATION",
    revisedMatchDuration: "Standard overs maintained on Reserve Day",
    rescheduledFixtures: [],
    tiebreakerRuling: "Points split evenly or higher league standing advances if knockout match impossible",
    directorOfficialStatement: "Due to adverse conditions, tournament matches are moved to the designated reserve schedule to ensure safety and fair play.",
    emergencyWhatsAppBroadcast: "⚠️ WEATHER ALERT: Matches rescheduled due to rain. Please check revised timetable below."
  };
}

const meta = $('Prepare Contingency Prompt').first().json;

return [{
  json: {
    status: "success",
    tournamentName: meta.tournamentName,
    disruptionReason: meta.disruptionReason,
    plannedAt: new Date().toISOString(),
    contingencyPlan: parsedPlan
  }
}];
